<template>
  <section class="property-process-center">
    <div class="process-shell">
      <aside class="process-context-rail">
        <header class="process-center-header"><div><span class="process-center-kicker">{{ $t('processCenter.kicker') }}</span><h2>{{ $t('processCenter.title') }}</h2><p>{{ $t('processCenter.description') }}</p></div></header>
        <button type="button" class="process-start-button process-rail-start" @click="openSetupWizard">＋ 开始新租房流程</button>
        <section class="process-property-picker">
          <div class="process-picker-head"><strong>{{ $t('processCenter.selectProperty') }}</strong><span>{{ properties.length }}</span></div>
          <input v-if="properties.length > 1" v-model.trim="search" type="search" :placeholder="$t('processCenter.searchPlaceholder')">
          <div v-if="loading" class="process-state">{{ $t('processCenter.loading') }}</div>
          <div v-else-if="error" class="process-state error"><span>{{ error }}</span><button type="button" @click="loadProperties">{{ $t('processCenter.retry') }}</button></div>
          <div v-else-if="!filteredProperties.length" class="process-state">{{ $t('processCenter.noProperties') }}</div>
          <div v-else class="process-property-list"><button v-for="property in filteredProperties" :key="property.rowKey" type="button" class="process-property-option" :class="{ active: selectedPropertyKey === property.rowKey }" @click="selectProperty(property)"><span class="process-property-icon">⌂</span><span><strong>{{ property.projectName || $t('processCenter.unsetProject') }}</strong><small>{{ property.unitNo || $t('processCenter.unsetUnit') }} · {{ property.ownerName || $t('processCenter.unsetOwner') }}</small></span><i>›</i></button></div>
        </section>
      </aside>
      <div class="process-workspace">
    <section v-if="journeySteps.length" class="process-journey-map">
      <div class="process-journey-head"><div class="process-journey-title"><strong>租房全流程</strong><small>从房产准备到结束租约 · 附件签约独立办理</small></div><div class="process-journey-summary"><span>{{ journeyCompletedCount }}/{{ journeySteps.length }} 已完成</span><strong v-if="journeyCurrentStep">当前 · {{ journeyCurrentStep.title }}</strong><strong v-else class="is-complete">流程已完成</strong></div></div>
      <div class="process-journey-track">
        <button v-for="(step, index) in journeySteps" :key="step.key" type="button" :class="[`is-${step.status}`, { active: selectedJourneyStep?.key === step.key }]" :aria-pressed="selectedJourneyStep?.key === step.key" @click="selectJourneyStep(step)"><span>{{ step.status === 'completed' ? '✓' : index + 1 }}</span><strong>{{ step.title }}</strong></button>
      </div>
    </section>
    <div v-if="setupWizardOpen" class="process-setup-backdrop" @click.self="closeSetupWizard">
      <form class="process-setup-dialog" @submit.prevent="setupStep < 3 ? nextSetupStep() : submitSetupWizard()">
        <header><div><span class="process-center-kicker">开始新租房流程</span><h3>{{ setupStep === 1 ? '建立或选择建案' : setupStep === 2 ? '建立或选择业主' : '新增房产并进入流程' }}</h3><p>完成后会自动选中新房产，继续办理交房、委托、租约和入住。</p></div><button type="button" class="rental-action-close" @click="closeSetupWizard">×</button></header>
        <div class="process-setup-progress"><span v-for="step in 3" :key="step" :class="{ active: setupStep === step, complete: setupStep > step }"><i>{{ setupStep > step ? '✓' : step }}</i>{{ step === 1 ? '建案' : step === 2 ? '业主' : '房产' }}</span></div>
        <div class="process-setup-body">
          <template v-if="setupStep === 1">
            <div class="process-setup-mode"><button type="button" :class="{ active: setupProjectMode === 'existing' }" @click="setupProjectMode = 'existing'">选择已有建案</button><button type="button" :class="{ active: setupProjectMode === 'new' }" @click="setupProjectMode = 'new'">建立新建案</button></div>
            <label v-if="setupProjectMode === 'existing'" class="process-setup-wide">建案<select v-model="setupProjectId"><option value="">请选择建案</option><option v-for="project in setupProjects" :key="project.id" :value="String(project.id)">{{ project.name }}{{ project.city ? ` · ${project.city}` : '' }}</option></select></label>
            <div v-else class="process-setup-grid"><label>建案编码<input v-model.trim="setupProjectForm.projectCode" placeholder="例如：CCPS-001"></label><label>建案名称<input v-model.trim="setupProjectForm.name" placeholder="请输入建案名称"></label><label>州属<select v-model="setupProjectForm.state" @change="setupProjectForm.city = ''"><option value="">请选择州属</option><option v-for="location in malaysiaLocations" :key="location.state" :value="location.state">{{ location.state }}</option></select></label><label>城市 / 区县<select v-model="setupProjectForm.city" :disabled="!setupProjectForm.state"><option value="">请选择城市 / 区县</option><option v-for="area in setupAreaOptions" :key="area" :value="area">{{ area }}</option></select></label><label class="process-setup-wide">详细地址<input v-model.trim="setupProjectForm.address"></label></div>
          </template>
          <template v-else-if="setupStep === 2">
            <div class="process-setup-mode"><button type="button" :class="{ active: setupOwnerMode === 'existing' }" @click="setupOwnerMode = 'existing'">选择已有业主</button><button type="button" :class="{ active: setupOwnerMode === 'new' }" @click="setupOwnerMode = 'new'">建立新业主</button></div>
            <label v-if="setupOwnerMode === 'existing'" class="process-setup-wide">业主<select v-model="setupOwnerId"><option value="">请选择业主</option><option v-for="owner in setupOwners" :key="owner.id" :value="String(owner.id)">{{ owner.fullName }}{{ owner.phone ? ` · ${owner.phone}` : '' }}</option></select></label>
            <div v-else class="process-setup-grid"><label>业主姓名<input v-model.trim="setupOwnerForm.fullName"></label><label>行动电话<input v-model.trim="setupOwnerForm.mobilePhone" placeholder="例如：+60 12-345 6789"></label><label>邮箱<input v-model.trim="setupOwnerForm.email" type="email"></label><label>身份证号<input v-model.trim="setupOwnerForm.identityNo"></label><label>护照号码<input v-model.trim="setupOwnerForm.passportNo"></label></div>
          </template>
          <div v-else class="process-setup-grid">
            <label>栋<input v-model.trim="setupPropertyForm.building"></label><label>楼层<input v-model.trim="setupPropertyForm.floorNo"></label><label>单位编号<input v-model.trim="setupPropertyForm.unitNo"></label><label>户型<input v-model.trim="setupPropertyForm.unitType"></label><label>面积（㎡）<input v-model.number="setupPropertyForm.areaSqm" type="number" min="0" step="0.01"></label><label>房间数<input v-model.number="setupPropertyForm.bedroomCount" type="number" min="0"></label><label>房产阶段<input value="已交房" disabled></label><label>实际交房日期<input v-model="setupPropertyForm.actualHandoverDate" type="date" required></label><label>房产总价（RM）<input v-model.number="setupPropertyForm.purchasePrice" type="number" min="0" step="0.01"></label><label>持有比例（%）<input v-model.number="setupPropertyForm.ownershipPercent" type="number" min="0.01" max="100" step="0.01"></label><label class="process-setup-wide process-setup-rental"><input v-model="setupPropertyForm.services" type="checkbox" value="RENTAL"> 建立后启用出租流程</label>
          </div>
          <p v-if="setupError" class="rental-action-error">{{ setupError }}</p>
        </div>
        <footer><button type="button" class="rental-action-secondary" @click="setupStep === 1 ? closeSetupWizard() : setupStep--">{{ setupStep === 1 ? '取消' : '上一步' }}</button><button type="submit" class="rental-action-primary" :disabled="setupBusy">{{ setupBusy ? '处理中…' : setupStep < 3 ? '下一步' : '建立并进入流程' }}</button></footer>
      </form>
    </div>
    <div class="process-center-layout">
      <main class="process-center-main">
        <div v-if="loading" class="process-center-empty">{{ $t('processCenter.loading') }}</div>
        <div v-else-if="error" class="process-center-empty error"><strong>{{ $t('processCenter.loadFailed') }}</strong><span>{{ error }}</span><button type="button" @click="loadProperties">{{ $t('processCenter.retry') }}</button></div>
        <div v-else-if="workspaceLoading" class="process-center-empty">{{ $t('processCenter.loadingWorkspace') }}</div>
        <div v-else-if="workspaceError" class="process-center-empty error"><strong>{{ $t('processCenter.loadFailed') }}</strong><span>{{ workspaceError }}</span><button type="button" @click="loadWorkspace(selectedProperty)">{{ $t('processCenter.retry') }}</button></div>
        <div v-else-if="!selectedProperty" class="process-center-empty"><strong>{{ $t('processCenter.chooseProperty') }}</strong><span>{{ $t('processCenter.choosePropertyHint') }}</span></div>
        <template v-else>
          <div class="process-selected-property"><div><span class="process-center-kicker">{{ $t('processCenter.selectedProperty') }}</span><h3>{{ propertyTitle }}</h3><p>{{ propertyOwner }} · {{ selectedProperty.unitType || $t('processCenter.unitNotSet') }}</p></div><div class="process-property-tags"><span>{{ stageLabel }}</span></div></div>
          <section v-if="selectedJourneyStep" class="process-step-page">
            <header class="process-step-page-head"><div class="process-step-heading"><span class="process-step-number">{{ journeyStepNumber(selectedJourneyStep) }}</span><div><span class="process-center-kicker">当前查看</span><h4>{{ selectedJourneyStep.title }}</h4><p>{{ journeyStepDescription(selectedJourneyStep) }}</p></div></div><div class="process-step-actions"><span :class="`is-${selectedJourneyStep.status}`">{{ stageStatusLabel(selectedJourneyStep) }}</span><button v-if="selectedSystemStage?.primaryAction && !selectedJourneyStep.operationsTab" type="button" :disabled="!canPerformStageAction(selectedSystemStage)" :title="roleActionHint(selectedSystemStage)" @click="openStage(selectedSystemStage)">{{ stageActionLabel(selectedSystemStage) }}</button></div></header>
            <div v-if="selectedJourneyStep.key === 'propertySetup'" class="process-step-facts"><article><span>建案</span><strong>{{ selectedProperty.projectName || '—' }}</strong></article><article><span>业主</span><strong>{{ propertyOwner }}</strong></article><article><span>房产单位</span><strong>{{ propertyTitle }}</strong></article><article><span>交房状态</span><strong>{{ stageLabel }} · {{ selectedProperty.actualHandoverDate || '—' }}</strong></article><article class="is-wide"><span>详细地址</span><strong>{{ selectedProperty.address || workspace?.property?.address || '—' }}</strong></article></div>
            <div v-else-if="selectedJourneyStep.key === 'mandateAuthorization'" class="process-step-facts"><article><span>委托编号</span><strong>{{ rentalWorkbench.currentMandate?.mandateNo || '尚未建立' }}</strong></article><article><span>委托状态</span><strong>{{ rentalWorkbench.currentMandate?.status || '—' }}</strong></article><article><span>委托期间</span><strong>{{ rentalWorkbench.currentMandate?.startDate || '—' }} → {{ rentalWorkbench.currentMandate?.endDate || '—' }}</strong></article></div>
            <div v-else-if="selectedJourneyStep.key === 'tenantSetup'" class="process-step-facts"><article><span>租客姓名</span><strong>{{ currentTenant?.fullName || rentalWorkbench.currentLease?.tenantName || '尚未建立' }}</strong></article><article><span>联系电话</span><strong>{{ currentTenant?.phone || '—' }}</strong></article><article><span>邮箱</span><strong>{{ currentTenant?.email || '—' }}</strong></article></div>
            <div v-else-if="selectedJourneyStep.key === 'leaseSetup'" class="process-step-facts"><article><span>租约编号</span><strong>{{ rentalWorkbench.currentLease?.leaseNo || rentalWorkbench.currentLease?.id || '尚未建立' }}</strong></article><article><span>月租金</span><strong>RM {{ rentalWorkbench.currentLease?.monthlyRent || 0 }}</strong></article><article><span>租约期间</span><strong>{{ rentalWorkbench.currentLease?.startDate || '—' }} → {{ rentalWorkbench.currentLease?.endDate || '—' }}</strong></article></div>
            <div v-else-if="selectedJourneyStep.key === 'moveInCollection'" class="process-step-facts"><article><span>入住交接</span><strong>{{ selectedJourneyStep.status === 'completed' ? '已完成' : '待办理' }}</strong></article><article><span>入住租客</span><strong>{{ currentTenant?.fullName || rentalWorkbench.currentLease?.tenantName || '—' }}</strong></article><article><span>负责角色</span><strong>{{ stageOwner(selectedSystemStage) }}</strong></article></div>
            <div v-else-if="selectedJourneyStep.key === 'billingOperations'" class="process-step-operations"><div class="rental-operations-launch-copy"><span class="rental-operations-launch-icon">¥</span><div><strong>租金与账单</strong><p>处理租金账单、费用明细和收款记录。</p><small v-if="rentalWorkbench.currentLease">当前租约：{{ rentalWorkbench.currentLease.leaseNo || rentalWorkbench.currentLease.id }}</small><small v-else>建立租约并完成入住后才能办理</small></div></div><button type="button" class="rental-action-primary rental-operations-open-button" :disabled="!rentalWorkbench.currentLease" @click="openOperationsCenter('billing')">进入租金与账单 <span aria-hidden="true">→</span></button></div>
            <div v-else-if="selectedJourneyStep.key === 'maintenanceOperations'" class="process-step-operations"><div class="rental-operations-launch-copy"><span class="rental-operations-launch-icon">⌁</span><div><strong>维修与运营</strong><p>处理维修工单、供应商和日常运营事项。</p><small v-if="rentalWorkbench.currentLease">当前租约：{{ rentalWorkbench.currentLease.leaseNo || rentalWorkbench.currentLease.id }}</small><small v-else>建立租约并完成入住后才能办理</small></div></div><button type="button" class="rental-action-primary rental-operations-open-button" :disabled="!rentalWorkbench.currentLease" @click="openOperationsCenter('maintenance')">进入维修与运营 <span aria-hidden="true">→</span></button></div>
            <div v-else-if="selectedJourneyStep.key === 'leaseClosure'" class="process-step-facts"><article><span>当前租约</span><strong>{{ rentalWorkbench.currentLease?.leaseNo || rentalWorkbench.currentLease?.id || '无进行中租约' }}</strong></article><article><span>最近结束日期</span><strong>{{ rentalWorkbench.leaseClosure?.endDate || '—' }}</strong></article><article><span>退租交接附件</span><strong>{{ rentalWorkbench.leaseClosure?.handoverReportReady ? '已生成' : '可选，不阻塞流程' }}</strong></article></div>
            <p v-if="selectedSystemStage?.blockingReasonKey" class="process-step-message is-blocked">{{ stageBlockingReason(selectedSystemStage) }}</p><p v-else-if="selectedSystemStage?.missingItems?.length" class="process-step-message">下一步需要：{{ stageMissingItems(selectedSystemStage) }}</p>
          </section>
          <section v-if="activeAction" class="rental-action-panel">
            <div class="rental-action-panel-head"><div><span class="process-center-kicker">{{ $t('processCenter.actionPanelTitle') }}</span><h4>{{ actionPanelTitle }}</h4><p>{{ actionPanelHint }}</p></div><button type="button" class="rental-action-close" @click="closeAction">×</button></div>
            <form class="rental-action-form" @submit.prevent="activeAction === 'close_lease' ? submitCloseLease() : activeAction === 'complete_move_out_handover' ? submitMoveOutHandover() : submitAction()">
              <div class="rental-action-grid" v-if="activeAction === 'create_mandate'">
                <label>{{ $t('processCenter.actionFields.startDate') }}<input v-model="actionForm.startDate" type="date" required></label>
                <label>{{ $t('processCenter.actionFields.endDate') }}<input v-model="actionForm.endDate" type="date"></label>
                <label>{{ $t('processCenter.actionFields.managementFee') }}<input v-model.number="actionForm.managementFee" type="number" min="0" step="0.01"></label>
                <label>{{ $t('processCenter.actionFields.commissionPercent') }}<input v-model.number="actionForm.commissionPercent" type="number" min="0" step="0.01"></label>
              </div>
              <div class="rental-action-grid" v-else-if="['complete_handover', 'complete_move_out_handover', 'complete_property_data'].includes(activeAction)">
                <label>{{ $t('processCenter.actionFields.unitNo') }}<input v-model.trim="actionForm.unitNo" required></label>
                <label>{{ $t('processCenter.actionFields.unitType') }}<input v-model.trim="actionForm.unitType"></label>
                <label>{{ $t('processCenter.actionFields.building') }}<input v-model.trim="actionForm.building"></label>
                <label>{{ $t('processCenter.actionFields.floorNo') }}<input v-model.trim="actionForm.floorNo"></label>
                <label>{{ $t('processCenter.actionFields.bedroomCount') }}<input v-model.number="actionForm.bedroomCount" type="number" min="0" max="50"></label>
                <label>{{ $t('processCenter.actionFields.purchasePrice') }}<input v-model.number="actionForm.purchasePrice" type="number" min="0" step="0.01"></label>
                <label>{{ $t('processCenter.actionFields.actualHandoverDate') }}<input v-model="actionForm.actualHandoverDate" type="date"></label>
                  <template v-if="['complete_handover', 'complete_move_out_handover'].includes(activeAction)">
                    <label>{{ $t('processCenter.actionFields.conditionSummary') }}<input v-model.trim="actionForm.conditionSummary"></label>
                    <label>{{ $t('processCenter.actionFields.keyCount') }}<input v-model.number="actionForm.keyCount" type="number" min="0"></label>
                    <label>{{ $t('processCenter.actionFields.accessCardCount') }}<input v-model.number="actionForm.accessCardCount" type="number" min="0"></label>
                    <label>{{ $t('processCenter.actionFields.waterMeter') }}<input v-model.trim="actionForm.waterMeter"></label>
                    <label>{{ $t('processCenter.actionFields.electricityMeter') }}<input v-model.trim="actionForm.electricityMeter"></label>
                    <label>{{ $t('processCenter.actionFields.receivedBy') }}<input v-model.trim="actionForm.receivedBy"></label>
                    <label class="rental-action-wide">{{ $t('processCenter.actionFields.handoverNotes') }}<textarea v-model.trim="actionForm.handoverNotes" rows="3"></textarea></label>
                  </template>
                  <div class="rental-action-wide rental-checklist-launcher">
                    <div><strong>{{ $t('processCenter.actionFields.handoverChecklist') }}</strong><small v-if="actionForm.handoverChecklist?.length">{{ actionForm.handoverChecklist.length }} {{ $t('processCenter.actionFields.checklistItems') }}</small><small v-else>{{ $t('processCenter.actionFields.checklistEmpty') }}</small></div>
                    <button type="button" class="rental-action-primary rental-checklist-edit-primary" @click="checklistModalOpen = true">{{ $t('processCenter.actionFields.editChecklist') }}</button>
                  </div>
                  <div class="rental-action-wide rental-handover-photo-controls">
                    <label>{{ $t('processCenter.actionFields.handoverPhotoSection') }}<select v-model="actionForm.handoverPhotoSection"><option v-for="section in handoverPhotoSectionOptions" :key="section.value" :value="section.value">{{ section.label }}</option></select></label>
                    <label>{{ $t('processCenter.actionFields.handoverPhotos') }}<input type="file" accept="image/*" multiple @change="handleHandoverPhotos"><small>{{ actionForm.handoverPhotoItems?.length || 0 }} {{ $t('processCenter.actionFields.filesSelected') }}</small></label>
                  </div>
                  <div v-if="actionForm.handoverPhotoItems?.length" class="rental-action-wide rental-handover-new-photo-list">
                    <article v-for="photo in actionForm.handoverPhotoItems" :key="photo.id" class="rental-handover-photo-card">
                      <img class="rental-handover-photo-thumb" :src="photo.previewUrl" :alt="photo.file.name">
                      <div class="rental-handover-photo-card-body"><strong>{{ photo.file.name }}</strong><label>{{ $t('processCenter.actionFields.photoModule') }}<select v-model="photo.section"><option v-for="section in handoverPhotoSectionOptions" :key="section.value" :value="section.value">{{ section.label }}</option></select></label></div>
                      <button type="button" class="rental-handover-photo-remove" :aria-label="$t('processCenter.actionFields.removePhoto')" @click="removeHandoverPhoto(photo)">×</button>
                    </article>
                  </div>
                  <div v-if="workspaceRelated.photos?.length" class="rental-action-wide rental-handover-reuse-panel">
                    <div><strong>{{ $t('processCenter.actionFields.reuseHandoverPhotos') }}</strong><small>{{ $t('processCenter.actionFields.reuseHandoverPhotosHint') }}</small></div>
                    <label v-for="photo in workspaceRelated.photos" :key="photo.id" class="rental-handover-reuse-option"><input v-model="actionForm.reusableHandoverPhotoIds" type="checkbox" :value="photo.id"><img class="rental-handover-reuse-thumb" :src="photo.previewUrl || reusablePhotoUrl(photo)" :alt="photo.title || photo.originalName || $t('processCenter.actionFields.propertyPhoto')" @error="loadReusablePhotoPreview(photo)"><span><strong>{{ photo.title || photo.originalName || $t('processCenter.actionFields.propertyPhoto') }}</strong><small class="rental-handover-reuse-section">{{ photoSectionLabel(photo) }}</small></span></label>
                  </div>
                  <div class="rental-action-wide rental-handover-report-launcher">
                    <div><strong>{{ $t('processCenter.actionFields.handoverReport') }}</strong><small>{{ $t('processCenter.actionFields.handoverReportHint') }}</small><small v-if="workspaceRelated.handovers?.length">{{ $t('processCenter.actionFields.handoverReportCount', { count: workspaceRelated.handovers.length }) }}</small></div>
                    <button type="button" class="rental-action-primary" :disabled="actionBusy || !actionForm.handoverChecklist?.length" @click="generateHandoverReport">{{ $t('processCenter.actionFields.generateHandoverReport') }}</button>
                  </div>
                  <p v-if="handoverReportFeedback" class="rental-action-feedback success">{{ handoverReportFeedback }}</p>
                </div>
              <div class="rental-action-grid" v-else-if="activeAction === 'close_lease'">
                <label>{{ $t('processCenter.actionFields.endDate') }}<input v-model="actionForm.endDate" type="date" :min="rentalWorkbench.currentLease?.startDate" :max="todayDate()" required></label>
                <label>{{ $t('processCenter.actionFields.closeReason') }}<select v-model="actionForm.closureReason"><option value="normal_expiry">{{ $t('processCenter.actionFields.closeReasonNormal') }}</option><option value="early_termination">{{ $t('processCenter.actionFields.closeReasonEarly') }}</option></select></label>
                <label class="rental-action-wide">{{ $t('processCenter.actionFields.closeNotes') }}<textarea v-model.trim="actionForm.closureNotes" rows="3"></textarea></label>
              </div>
              <div v-else-if="activeAction === 'create_tenant'" class="rental-tenant-picker">
                <label class="rental-tenant-existing">{{ $t('processCenter.actionFields.existingTenant') }}<select v-model="actionForm.existingTenantId"><option value="">{{ $t('processCenter.actionFields.noExistingTenant') }}</option><option v-for="tenant in workspaceRelated.tenants" :key="tenant.id" :value="String(tenant.id)">{{ tenant.name }}</option></select><small>{{ $t('processCenter.actionFields.existingTenantHint') }}</small></label>
                <div v-if="!actionForm.existingTenantId" class="rental-action-grid">
                  <label>{{ $t('processCenter.actionFields.tenantName') }}<input v-model.trim="actionForm.tenantName" required></label>
                  <label>{{ $t('processCenter.actionFields.tenantEmail') }}<input v-model.trim="actionForm.tenantEmail" type="email"></label>
                  <label>{{ $t('processCenter.actionFields.tenantPhone') }}<input v-model.trim="actionForm.tenantPhone"></label>
                  <label>{{ $t('processCenter.actionFields.tenantIdentity') }}<input v-model.trim="actionForm.tenantIdentity"></label>
                </div>
              </div>
              <div class="rental-action-grid" v-else-if="activeAction === 'create_lease'">
                <label>{{ $t('processCenter.actionFields.startDate') }}<input v-model="actionForm.startDate" type="date" :min="rentalWorkbench.currentMandate?.startDate || undefined" :max="rentalWorkbench.currentMandate?.endDate || undefined" required></label>
                <label>{{ $t('processCenter.actionFields.endDate') }}<input v-model="actionForm.endDate" type="date" :min="rentalWorkbench.currentMandate?.startDate || actionForm.startDate || undefined" :max="rentalWorkbench.currentMandate?.endDate || undefined" required></label>
                <label>{{ $t('processCenter.actionFields.monthlyRent') }}<input v-model.number="actionForm.monthlyRent" type="number" min="0.01" step="0.01" required></label>
                <label>{{ $t('processCenter.actionFields.depositAmount') }}<input v-model.number="actionForm.depositAmount" type="number" min="0" step="0.01"></label>
                <label>{{ $t('processCenter.actionFields.paymentDay') }}<input v-model.number="actionForm.paymentDay" type="number" min="1" max="31" required></label>
                <small v-if="rentalWorkbench.currentMandate?.startDate || rentalWorkbench.currentMandate?.endDate" class="rental-lease-term-hint">{{ $t('processCenter.actionFields.leaseTermHint', { startDate: rentalWorkbench.currentMandate?.startDate || '—', endDate: rentalWorkbench.currentMandate?.endDate || '—' }) }}</small>
              </div>
              <div class="rental-action-grid" v-else-if="activeAction === 'create_first_invoice'">
                <label>{{ $t('processCenter.actionFields.billingMonth') }}<input v-model="actionForm.billingMonth" type="month" required></label>
              </div>
              <p v-if="actionError" class="rental-action-error">{{ actionError }}</p>
