        <header class="operations-center-head"><div><span class="process-center-kicker">{{ $t('processCenter.operationsLeaseTitle') }}</span><h3>{{ $t('processCenter.operationsRenewalTitle') }}</h3><p>{{ propertyTitle }} · {{ operationsWorkspace?.lease?.tenantName || rentalWorkbench.currentLease?.tenantName || propertyOwner }}</p></div><button type="button" class="rental-action-close" @click="closeOperationsRenewal">×</button></header>
        <form class="operations-renewal-body" @submit.prevent="submitOperationsRenewal"><p class="operations-renewal-hint">续约会追加在当前租约下，每一期的日期、租金和附件都会独立保留。</p><div v-if="operationsRenewalPeriods.length" class="operations-renewal-periods"><div v-for="period in operationsRenewalPeriods" :key="period.id"><strong>第 {{ period.periodNo }} 期</strong><span>{{ period.startDate }} 至 {{ period.endDate }}</span><span>RM {{ formatOperationsAmount(period.monthlyRent) }}/月</span><em>{{ period.contractDocumentId ? '已有当期附件' : '暂无当期附件' }}</em></div></div><div class="operations-inline-grid"><label>{{ $t('processCenter.operationsRenewalStartDate') }}<input v-model="operationsRenewalForm.startDate" type="date" :min="operationsRenewalMinDate" readonly required></label><label>{{ $t('processCenter.operationsRenewalEndDate') }}<input v-model="operationsRenewalForm.endDate" type="date" :min="operationsRenewalMinDate" required></label><label>{{ $t('processCenter.operationsRenewalMonthlyRent') }}<input v-model.number="operationsRenewalForm.monthlyRent" type="number" min="0.01" step="0.01" required></label><label>{{ $t('processCenter.operationsRenewalDeposit') }}<input v-model.number="operationsRenewalForm.depositAmount" type="number" min="0" step="0.01" required></label><label>{{ $t('processCenter.operationsRenewalPaymentDay') }}<input v-model.number="operationsRenewalForm.paymentDay" type="number" min="1" max="31" required></label><label>{{ $t('processCenter.operationsRenewalCalculationMethod') }}<select v-model="operationsRenewalForm.rentCalculationMethod"><option value="daily_prorated">{{ $t('legacy.t_1e5825e68267') }}</option></select></label><label class="operations-inline-wide">本期续约附件<input type="file" accept="application/pdf,image/jpeg,image/png" @change="selectOperationsRenewalContract"><small>单独绑定到本期，不会覆盖原合同。</small></label></div><p v-if="operationsRenewalError" class="rental-action-error">{{ operationsRenewalError }}</p><footer class="operations-work-order-detail-footer"><button type="button" class="rental-action-secondary" @click="closeOperationsRenewal">{{ $t('processCenter.operationsFormCancel') }}</button><button type="submit" class="rental-action-primary" :disabled="operationsRenewalSaving">{{ operationsRenewalSaving ? $t('legacy.t_2cd5496ec548') : $t('processCenter.operationsRenewalSubmit') }}</button></footer></form>
