<script>
import { adminPropertyPhotoContentUrl, closeAdminLease, completeAdminMaintenance, confirmAdminFinanceReview, confirmAdminRentCollection, createAdminExpense, createAdminLease, createAdminLeaseFirstInvoice, createAdminLeaseRenewal, createAdminOwner, createAdminOwnerProperty, createAdminProject, createAdminPropertyHandoverChecklistItem, createAdminPropertyHandoverReport, createAdminPropertyOperationsCharge, createAdminPropertyOperationsWorkOrder, createAdminPropertyPhoto, createAdminRentalMandate, createAdminTenant, deleteAdminExpense, deleteAdminPropertyHandoverChecklistItem, downloadAdminPropertyHandoverReport, fetchAdminExpenses, fetchAdminFinanceReviews, fetchAdminLeasePayments, fetchAdminLeasePeriods, fetchAdminLeaseRentInvoices, fetchAdminMaintenanceDetail, fetchAdminMaintenanceHandling, fetchAdminMaintenanceOptions, fetchAdminOwners, fetchAdminProjects, fetchAdminProperties, fetchAdminPropertyAttachments, fetchAdminPropertyCashflows, fetchAdminPropertyHandover, fetchAdminPropertyHandoverChecklist, fetchAdminPropertyHandoverReports, fetchAdminPropertyMaintenance, fetchAdminPropertyOperations, fetchAdminPropertyPhotos, fetchAdminPropertyWorkspaceById, fetchAdminRentalMandates, fetchAdminTenancyOptions, rejectAdminFinanceReview, saveAdminPropertyHandover, saveAdminPropertyWorkspaceBasic, sendAdminRentReminder, updateAdminExpense, updateAdminPropertyHandoverChecklistItem, uploadAdminLeaseContract, uploadAdminLeaseRenewalContract, uploadAdminMaintenancePhotos } from '../services/propertyApi';
import { navigate } from '../router';
import { malaysiaLocations } from '../data/malaysiaLocations';
import { buildRentalWorkbench, selectCurrentRentalMandate } from '../utils/rentalCycleWorkbench';
import { rentalLeaseTermError } from '../utils/rentalLeaseValidation';

const dateAfter = (value, days) => { const [year, month, day] = String(value || '').slice(0, 10).split('-').map(Number); if (!year || !month || !day) return ''; const date = new Date(Date.UTC(year, month - 1, day)); date.setUTCDate(date.getUTCDate() + days); return date.toISOString().slice(0, 10); };

const HANDOVER_CATEGORIES = ['鑰匙 Keys', '門禁卡 Access Card', '遙控器 Remote Control', '客廳 Living Room', '飯廳 Dining Room', '廚房 Kitchen', '主臥室 Master Bedroom', '主浴室 Master Bathroom'];
const HANDOVER_PHOTO_SECTIONS = [
  { value: '鑰匙、通行卡和遙控器照片 / Keys, Access Card & Remote Control', label: '鑰匙、通行卡和遙控器 / Keys, Access Card & Remote Control' },
  { value: '客廳照片 / Living Room', label: '客廳 / Living Room' },
  { value: '飯廳照片 / Dining Room', label: '飯廳 / Dining Room' },
  { value: '廚房照片 / Kitchen', label: '廚房 / Kitchen' },
  { value: '主臥室照片 / Master Bedroom', label: '主臥室 / Master Bedroom' },
  { value: '主浴室照片 / Master Bathroom', label: '主浴室 / Master Bathroom' },
  { value: '瑕疵 (扣租客押金) / Defects (Deduct From Deposit)', label: '瑕疵（租客押金） / Defects (Tenant Deposit)' },
  { value: '瑕疵 (询问屋主是否要维修) / Defects (Ask Owner If Repairs Are Needed)', label: '瑕疵（业主维修） / Defects (Owner Repairs)' },
];

export default {
  name: 'AdminPropertyProcessWorkspace',
  inject: ['page'],
  data() { return {
    malaysiaLocations, properties: [], selectedPropertyKey: '', selectedProperty: null, selectedJourneyKey: '', workspace: null, currentTenant: null, workspaceRelated: this.emptyRelatedData(), search: '', loading: false, error: '', workspaceLoading: false, workspaceError: '',
    setupWizardOpen: false, setupStep: 1, setupBusy: false, setupError: '', setupProjects: [], setupOwners: [], setupProjectMode: 'existing', setupOwnerMode: 'existing', setupProjectId: '', setupOwnerId: '',
    setupProjectForm: { projectCode: '', name: '', state: '', city: '', address: '', countryCode: 'MY', status: 'active' },
    setupOwnerForm: { fullName: '', mobilePhone: '', phone: '', email: '', identityNo: '', passportNo: '', status: 'active' },
    setupPropertyForm: { building: '', floorNo: '', unitNo: '', unitType: '', areaSqm: null, bedroomCount: 0, listingStatus: 'available', assetStage: 'OPERATING', actualHandoverDate: '', services: ['RENTAL'], purchasePrice: 0, ownershipPercent: 100, primary: true, startDate: new Date().toISOString().slice(0, 10) },
    activeAction: '', actionBusy: false, actionError: '', handoverReportFeedback: '', serviceManagerOpen: false, serviceManagerRows: [], serviceManagerSaving: false, serviceManagerError: '',
    operationsCenterOpen: false, operationsLoading: false, operationsError: '', operationsWorkspace: null, operationsOptions: { units: [], vendors: [] }, operationsVendors: [], operationsOptionsLoading: false, operationsExpensesLoading: false, operationsExpensesError: '', operationsExpenses: [], operationsExpenseReviewsLoading: false, operationsExpenseReviewsError: '', operationsExpenseReviews: [], operationsEditingExpenseId: null, operationsReviewDecision: 'confirm', operationsSelectedReview: null, operationsTab: 'overview', operationsMonth: new Date().toISOString().slice(0, 7), operationsFormType: '', operationsForm: {}, operationsWorkOrderDetailOpen: false, operationsWorkOrderDetailLoading: false, operationsWorkOrderDetailError: '', operationsSelectedWorkOrder: null, operationsWorkOrderDetail: null, operationsWorkOrderHandling: null, operationsWorkOrderHandlingOpen: false, operationsWorkOrderHandlingSaving: false, operationsWorkOrderHandlingError: '', operationsWorkOrderHandlingForm: { actualAmount: 0, settlementMethod: 'direct_payment', completionNote: '' }, operationsWorkOrderHandlingFiles: { before: [], after: [], invoice: [] }, operationsRenewalOpen: false, operationsRenewalSaving: false, operationsRenewalError: '', operationsRenewalContractFile: null, operationsRenewalPeriods: [], operationsRenewalForm: {},
    checklistModalOpen: false, checklistCategoryOpen: false, checklistCategoryMenuStyle: {}, handoverCategoryOptions: HANDOVER_CATEGORIES, handoverPhotoSectionOptions: HANDOVER_PHOTO_SECTIONS, actionForm: {},
  }; },
  computed: {
    setupAreaOptions() { return this.malaysiaLocations.find(location => location.state === this.setupProjectForm.state)?.areas || []; },
    filteredProperties() { const query = this.search.toLowerCase(); return this.properties.filter(property => this.isRentalControlEligible(property) && (!query || [property.projectName, property.unitNo, property.ownerName, property.city].some(value => String(value || '').toLowerCase().includes(query)))); },
    currentAdminRoles() { const user = this.page?.currentUser || {}; return [user.role, ...(Array.isArray(user.roles) ? user.roles : [])].filter(Boolean).map(value => String(value).toLowerCase()); },
    propertyTitle() { return (this.selectedProperty?.projectName || this.$t('processCenter.unsetProject')) + ' · ' + (this.selectedProperty?.unitNo || this.$t('processCenter.unsetUnit')); },
    propertyOwner() { return this.workspace?.owner?.fullName || this.selectedProperty?.ownerName || this.$t('processCenter.unsetOwner'); },
    stageLabel() { return this.selectedProperty?.assetStage === 'OPERATING' ? this.$t('processCenter.stageOperating') : this.selectedProperty?.assetStage === 'DISPOSED' ? this.$t('processCenter.stageDisposed') : this.$t('processCenter.stagePreHandover'); },
    leases() { return this.workspace?.leases || []; },
    rentalWorkbench() { return buildRentalWorkbench({ property: this.selectedProperty || {}, mandates: this.workspaceRelated.mandates, workspace: { ...(this.workspace || {}), tenant: this.currentTenant, profile: this.workspace?.profile, photos: this.workspaceRelated.photos, handoverChecklist: this.workspaceRelated.handoverChecklist, handovers: this.workspaceRelated.handovers, handover: this.workspaceRelated.handover }, invoices: this.workspaceRelated.invoices, payments: this.workspaceRelated.payments }); },
     currentTask() { return this.rentalWorkbench.currentTask; },
      operationsInvoice() { return this.operationsWorkspace ? this.operationsWorkspace.billing || null : this.rentalWorkbench.dailyOperations.currentInvoice || null; },
     operationsInvoicePaid() { return Boolean(this.operationsInvoice && Number(this.operationsInvoice.amountPaid || 0) >= Number(this.operationsInvoice.amountDue || 0)); },
     operationsCharges() { return this.operationsWorkspace?.charges || []; },
     operationsWorkOrders() { return this.operationsWorkspace?.workOrders || []; },
      operationsCurrentLeaseId() { return this.rentalWorkbench.currentLease?.id || this.rentalWorkbench.currentLease?.leaseId || null; },
      operationsCurrentTenantId() { return this.rentalWorkbench.currentLease?.tenantId || this.currentTenant?.id || null; },
      operationsWorkOrderReserveShortage() { const formAmount = Number(this.operationsWorkOrderHandlingForm.actualAmount || 0); const reserveAvailable = Number(this.operationsWorkOrderHandling?.reserveBalance || 0) - Number(this.operationsWorkOrderHandling?.reserveDeductedAmount || 0); return Math.max(0, formAmount - reserveAvailable); },
      operationsRenewalMinDate() { const latest = this.operationsRenewalPeriods.at(-1); const leaseEnd = latest?.endDate || this.operationsWorkspace?.lease?.endDate || this.rentalWorkbench.currentLease?.endDate; return leaseEnd ? dateAfter(leaseEnd, 1) : this.todayDate(); },
      operationsManagementTotal() { return this.formatOperationsAmount(this.operationsCharges.filter(item => item.chargeType === 'management').reduce((total, item) => total + Number(item.amount || 0), 0)); },
      operationsUtilitiesTotal() { return this.formatOperationsAmount(this.operationsCharges.filter(item => item.chargeType === 'utilities').reduce((total, item) => total + Number(item.amount || 0), 0)); },
      operationsOtherTotal() { return this.formatOperationsAmount(this.operationsCharges.filter(item => ['maintenance', 'other'].includes(item.chargeType)).reduce((total, item) => total + Number(item.amount || 0), 0)); },
      operationsSelectedExpenseUnit() { const unitId = Number(this.selectedProperty?.ownerUnitId || this.selectedProperty?.unitId || this.selectedProperty?.id); return (this.operationsOptions.units || []).find(item => Number(item.unitId) === unitId) || null; },
      operationsExpenseTotal() { return this.operationsExpenses.reduce((total, item) => total + Number(item.amount || 0), 0); },
      operationsPendingExpenseCount() { return this.operationsExpenseReviews.length; },
      operationsActiveMaintenanceCount() { return this.operationsWorkOrders.filter(item => !['completed', 'cancelled'].includes(item.status)).length; },
      operationsFormTitle() { return ({ charge: this.$t('processCenter.operationsFormChargeTitle'), workOrder: this.$t('processCenter.operationsFormWorkOrderTitle'), invoice: this.$t('processCenter.operationsFormInvoiceTitle'), receipt: this.$t('processCenter.operationsFormReceiptTitle'), expense: this.$t('processCenter.operationsCreateExpense'), expenseReview: this.operationsReviewDecision === 'confirm' ? this.$t('processCenter.operationsExpenseConfirm') : this.$t('processCenter.operationsExpenseReject') })[this.operationsFormType] || ''; },
      operationsFormHint() { return ({ charge: this.$t('processCenter.operationsFormChargeHint'), workOrder: this.$t('processCenter.operationsFormWorkOrderHint'), invoice: this.$t('processCenter.operationsFormInvoiceHint'), receipt: this.$t('processCenter.operationsFormReceiptHint'), expense: this.$t('processCenter.operationsExpenseHint'), expenseReview: this.$t('processCenter.operationsExpenseReviewHint') })[this.operationsFormType] || ''; },
      operationsFormSubmitLabel() { if (this.operationsFormType === 'expenseReview') return this.operationsReviewDecision === 'confirm' ? this.$t('processCenter.operationsExpenseConfirm') : this.$t('processCenter.operationsExpenseReject'); return this.operationsFormType === 'expense' ? (this.operationsEditingExpenseId ? this.$t('projectManagement.edit') : this.$t('processCenter.operationsCreateExpense')) : this.$t('processCenter.operationsFormSave'); },
    journeySteps() {
      if (!this.selectedProperty) return [];
      const titled = this.rentalWorkbench.stages.map(item => ({ ...item, title: item.key === 'propertySetup' ? '房产准备' : this.stageTitle(item) }));
      const byKey = Object.fromEntries(titled.map(item => [item.key, item]));
      const leasing = byKey.leasingSigning;
      const operations = byKey.rentalOperations;
      const mandateReady = byKey.mandateAuthorization?.status === 'completed';
      const tenantReady = Boolean(this.currentTenant?.id || this.rentalWorkbench.currentLease?.tenantId || this.rentalWorkbench.currentLease?.tenantName);
      const leaseReady = Boolean(this.rentalWorkbench.currentLease);
      const tenantSetup = {
        ...leasing,
        key: 'tenantSetup',
        title: '建立租客',
        sourceStageKey: 'leasingSigning',
        status: !mandateReady ? 'pending' : tenantReady ? 'completed' : 'in_progress',
        missingItems: !mandateReady ? ['mandate_activation'] : tenantReady ? [] : ['tenant'],
        primaryAction: !tenantReady && leasing?.primaryAction?.key === 'create_tenant' ? leasing.primaryAction : null,
      };
      const leaseSetup = {
        ...leasing,
        key: 'leaseSetup',
        title: '建立租约',
        sourceStageKey: 'leasingSigning',
        status: !tenantReady ? 'pending' : leaseReady ? 'completed' : 'in_progress',
        missingItems: !tenantReady ? ['tenant'] : leaseReady ? [] : ['lease'],
        primaryAction: tenantReady && !leaseReady && leasing?.primaryAction?.key === 'create_lease' ? leasing.primaryAction : null,
      };
      return [
        byKey.propertySetup,
        byKey.mandateAuthorization,
        tenantSetup,
        leaseSetup,
        byKey.moveInCollection,
        { ...operations, key: 'billingOperations', title: '租金与账单', sourceStageKey: 'rentalOperations', operationsTab: 'billing', primaryAction: null },
        { ...operations, key: 'maintenanceOperations', title: '维修与运营', sourceStageKey: 'rentalOperations', operationsTab: 'maintenance', primaryAction: null },
        byKey.leaseClosure,
      ].filter(Boolean);
    },
    journeyCompletedCount() { return this.journeySteps.filter(step => step.status === 'completed').length; },
    journeyCurrentStep() { return this.journeySteps.find(step => step.status !== 'completed') || null; },
    selectedJourneyStep() { return this.journeySteps.find(step => step.key === this.selectedJourneyKey) || this.journeyCurrentStep || this.journeySteps[this.journeySteps.length - 1] || null; },
    selectedSystemStage() { return this.selectedJourneyStep || null; },
    actionPanelTitle() { return this.activeAction ? this.$t('processCenter.actions.' + this.activeAction) : ''; },
    actionPanelHint() { return this.$t('processCenter.actionPanelHint'); },
    actionSubmitLabel() { return ['complete_handover', 'complete_property_data'].includes(this.activeAction) ? this.$t('processCenter.actionFields.savePreparation') : this.activeAction === 'create_tenant' && this.actionForm.existingTenantId ? this.$t('processCenter.actions.use_existing_tenant') : this.activeAction === 'create_first_invoice' ? this.$t('processCenter.actions.create_first_invoice') : this.$t('processCenter.actionFields.save'); },
  },
  watch: {
    operationsMonth() { if (this.operationsCenterOpen) Promise.all([this.loadOperationsWorkspace(), this.loadOperationsExpenses(), this.loadOperationsExpenseReviews()]); },
    operationsTab() { this.operationsFormType = ''; },
  },
  mounted() { this.loadProperties(); window.addEventListener('focus', this.refreshProcessState); },
  beforeUnmount() { window.removeEventListener('focus', this.refreshProcessState); },
  methods: {
    selectJourneyStep(step) { if (!step || this.actionBusy) return; if (this.activeAction) this.closeAction(); this.selectedJourneyKey = step.key; },
    journeyStepNumber(step) { const index = this.journeySteps.findIndex(item => item.key === step?.key); return index >= 0 ? index + 1 : '—'; },
    journeyStepDescription(step) {
      const descriptions = {
        propertySetup: '统一查看建案、业主、房产和交房资料。',
        mandateAuthorization: '建立后直接启用出租委托，签约附件不阻塞此步骤。',
        tenantSetup: '选择已有租客或建立新租客。',
        leaseSetup: '建立系统租约，合同附件在附件签约中独立办理。',
        moveInCollection: '完成入住交接并确认房产进入出租状态。',
        billingOperations: '集中处理租金、账单、费用和收款记录。',
        maintenanceOperations: '集中处理维修工单、供应商和运营事项。',
