    isRentalControlEligible(property) { return String(property?.assetStage || '').toUpperCase() === 'OPERATING'; },
    async openSetupWizard() {
      this.setupWizardOpen = true;
      this.setupStep = 1;
      this.setupError = '';
      this.setupBusy = true;
      this.setupProjectMode = 'existing';
      this.setupOwnerMode = 'existing';
      this.setupProjectId = '';
      this.setupOwnerId = '';
      this.setupProjectForm = { projectCode: '', name: '', state: '', city: '', address: '', countryCode: 'MY', status: 'active' };
      this.setupOwnerForm = { fullName: '', mobilePhone: '', phone: '', email: '', identityNo: '', passportNo: '', status: 'active' };
      this.setupPropertyForm = { building: '', floorNo: '', unitNo: '', unitType: '', areaSqm: null, bedroomCount: 0, listingStatus: 'available', assetStage: 'OPERATING', actualHandoverDate: '', services: ['RENTAL'], purchasePrice: 0, ownershipPercent: 100, primary: true, startDate: new Date().toISOString().slice(0, 10) };
      try {
        const [projectResponse, owners] = await Promise.all([fetchAdminProjects({ page: 1, pageSize: 500, status: 'active' }), fetchAdminOwners()]);
        this.setupProjects = projectResponse?.rows || [];
        this.setupOwners = (owners || []).filter(owner => owner.status === 'active');
        if (!this.setupProjects.length) this.setupProjectMode = 'new';
        if (!this.setupOwners.length) this.setupOwnerMode = 'new';
      } catch (error) {
        this.setupError = error.message || '基础资料加载失败';
      } finally {
        this.setupBusy = false;
      }
    },
    closeSetupWizard() { if (!this.setupBusy) this.setupWizardOpen = false; },
    nextSetupStep() {
      this.setupError = '';
      if (this.setupStep === 1) {
        if (this.setupProjectMode === 'existing' && !this.setupProjectId) return void (this.setupError = '请选择已有建案');
        if (this.setupProjectMode === 'new' && (!this.setupProjectForm.projectCode || !this.setupProjectForm.name)) return void (this.setupError = '请填写建案编码和名称');
      }
      if (this.setupStep === 2) {
        if (this.setupOwnerMode === 'existing' && !this.setupOwnerId) return void (this.setupError = '请选择已有业主');
        if (this.setupOwnerMode === 'new' && (!this.setupOwnerForm.fullName || !this.setupOwnerForm.mobilePhone)) return void (this.setupError = '请填写业主姓名和行动电话');
      }
      this.setupStep += 1;
    },
    async submitSetupWizard() {
      if (!this.setupPropertyForm.unitNo) { this.setupError = '请填写单位编号'; return; }
      if (!this.setupPropertyForm.actualHandoverDate) { this.setupError = '开始租房流程前必须填写实际交房日期'; return; }
      this.setupBusy = true;
      this.setupError = '';
      try {
        let projectId = Number(this.setupProjectId);
        if (this.setupProjectMode === 'new') {
          const project = await createAdminProject({ ...this.setupProjectForm, projectCode: this.setupProjectForm.projectCode.trim().toUpperCase(), name: this.setupProjectForm.name.trim(), address: this.setupProjectForm.address || null, state: this.setupProjectForm.state || null, city: this.setupProjectForm.city || null, countryCode: 'MY', status: 'active' });
          projectId = Number(project.id);
        }
        let ownerId = Number(this.setupOwnerId);
        if (this.setupOwnerMode === 'new') {
          const owner = await createAdminOwner({ ...this.setupOwnerForm, phone: this.setupOwnerForm.mobilePhone, status: 'active' });
          ownerId = Number(owner.id);
        }
        await createAdminOwnerProperty(ownerId, { ...this.setupPropertyForm, projectId, assetStage: 'OPERATING', expectedHandoverDate: null });
        this.setupWizardOpen = false;
        await this.loadProperties();
        const created = this.properties.find(property => String(property.ownerId) === String(ownerId) && property.unitNo === this.setupPropertyForm.unitNo);
        if (created) await this.selectProperty(created);
        this.page?.showToast?.('建案、业主与房产已接入完整租房流程');
      } catch (error) {
        this.setupError = error.message || '建立租房流程失败';
      } finally {
        this.setupBusy = false;
      }
    },
    normalizeWorkflowRole(value) { const role = String(value || '').toLowerCase(); if (role.includes('finance') || role.includes('account')) return 'finance'; if (role.includes('admin') || role.includes('operation') || role.includes('office')) return 'admin'; if (role.includes('business') || role.includes('leasing') || role.includes('sales')) return 'business'; return ''; },
    canPerformStageAction(stage) { const roles = this.currentAdminRoles.map(role => this.normalizeWorkflowRole(role)).filter(Boolean); if (!roles.length || roles.includes('admin') || this.currentAdminRoles.some(role => role === 'admin')) return true; const ownerRole = this.normalizeWorkflowRole(stage?.ownerRole); return !ownerRole || roles.includes(ownerRole); },
    roleActionHint(stage) { return this.canPerformStageAction(stage) ? '' : this.$t('processCenter.roleRestricted'); },
