        unitNo: property.unitNo || this.selectedProperty?.unitNo || '', unitType: property.unitType || this.selectedProperty?.unitType || '', building: property.building || '', floorNo: property.floorNo || '', bedroomCount: property.bedroomCount || 0, purchasePrice: property.purchasePrice || 0,
