        closureReason: 'early_termination', closureNotes: '', conditionSummary: '', keyCount: 0, accessCardCount: 0, waterMeter: '', electricityMeter: '', receivedBy: this.rentalWorkbench.leaseClosure?.tenantName || '', handoverNotes: '',
        handoverChecklist: (this.workspaceRelated.handoverChecklist || []).map(item => ({ ...item, defaultQuantity: item.defaultQuantity || '', notes: item.notes || '' })), removedHandoverChecklistIds: [], newChecklistCategory: '客廳 Living Room', newChecklistItem: '', handoverPhotoFiles: [], handoverPhotoSection: HANDOVER_PHOTO_SECTIONS[0].value, reusableHandoverPhotoIds: [],
