         else if (this.operationsFormType === 'expense') { if (this.operationsForm.settlementMethod === 'reserve' && !this.operationsSelectedExpenseUnit?.reserveAccountId) throw new Error('当前房产没有可用的预备金账户。'); if (this.operationsForm.settlementMethod === 'direct_payment' && this.operationsSelectedExpenseUnit?.directPaymentAllowed === false) throw new Error('业主已解约，不能新增代付款。'); const payload = { unitId: ownerUnitId, ...this.operationsForm, amount: Number(this.operationsForm.amount) }; if (this.operationsEditingExpenseId) await updateAdminExpense(this.operationsEditingExpenseId, payload); else await createAdminExpense(payload); await Promise.all([this.loadOperationsExpenses(), this.loadOperationsExpenseReviews()]); this.page?.showToast?.(this.operationsEditingExpenseId ? '开支记录已修改' : '开支已建立并送往财务确认'); }
         else { if (!this.operationsSelectedReview?.id || !String(this.operationsForm.note || '').trim()) throw new Error('请填写确认备注。'); if (this.operationsReviewDecision === 'confirm') await confirmAdminFinanceReview(this.operationsSelectedReview.id, this.operationsForm.note); else await rejectAdminFinanceReview(this.operationsSelectedReview.id, this.operationsForm.note); await Promise.all([this.loadOperationsExpenses(), this.loadOperationsExpenseReviews(), this.loadOperationsWorkspace()]); this.page?.showToast?.(this.operationsReviewDecision === 'confirm' ? '开支已确认' : '开支已退回修改'); }
         this.closeOperationsForm();
       } catch (error) { this.operationsError = error.message || this.$t('processCenter.loadFailed'); }
