/* Compact process workspace: keep one page scrollbar and prioritize the active step. */
.property-process-center{gap:12px;padding:14px 20px 24px}
.process-center-header{align-items:center;padding:0 2px}
.process-center-header>div:first-child{gap:3px}
.process-center-header h2{font-size:22px}
.process-header-actions{align-items:center}
.process-center-count{padding:8px 12px}
.process-start-button{height:40px}
.process-journey-map{gap:9px;padding:12px 16px}
.process-journey-head{align-items:center}
.process-journey-head>div:first-child{display:flex;align-items:center;gap:10px}
.process-journey-head strong{font-size:13px}
.process-journey-summary{display:flex;align-items:center;gap:10px}
.process-journey-summary>span{padding:4px 8px;border-radius:999px;background:#e9f7f7;color:#08717a;font-size:10px;font-weight:800;white-space:nowrap}
.process-journey-track{display:grid;grid-template-columns:repeat(8,minmax(112px,1fr));overflow-x:auto;padding:0 0 2px}
.process-journey-track article{min-width:0;padding-right:14px}
.process-journey-track article:not(:last-child)::after{top:13px;right:3px;width:9px}
.process-journey-track article>span{flex-basis:26px;width:26px;height:26px;font-size:10px}
.process-journey-track strong{font-size:10px}
.process-journey-track small{font-size:9px}
.process-center-layout{grid-template-columns:260px minmax(0,1fr);height:auto;min-height:0;align-items:start}
.process-property-picker{position:sticky;top:12px}
.process-property-list{max-height:calc(100vh - 250px)}
.process-center-main{height:auto;min-height:420px;padding:16px;overflow:visible}
.process-selected-property{padding:0 0 12px}
.process-selected-property h3{font-size:18px}
.rental-current-task{display:grid;grid-template-columns:minmax(0,1fr) auto;min-height:0;margin:12px 0 14px;padding:12px 14px}
.rental-current-task h4{margin:2px 0;font-size:15px}
.rental-current-task p{font-size:11px}
.rental-current-task small{display:inline-block;margin:4px 10px 0 0}
.process-center-section-head{margin:14px 0 9px}
.rental-stage-list{gap:8px}
.rental-stage-card{grid-template-columns:30px minmax(0,1fr) auto;gap:10px;padding:11px 14px}
.rental-stage-marker{width:27px;height:27px}
.rental-stage-body{gap:3px}
.rental-stage-title strong{font-size:12px}
.rental-stage-missing,.rental-stage-blocking{font-size:11px}
.rental-stage-actions{gap:4px}
@media(max-width:1100px){.process-journey-head{align-items:flex-start}.process-journey-summary small{display:none}.process-center-layout{grid-template-columns:230px minmax(0,1fr)}}
@media(max-width:850px){.process-center-layout{grid-template-columns:1fr}.process-property-picker{position:static}.process-property-list{max-height:230px}}
@media(max-width:700px){.process-journey-head>div:first-child{align-items:flex-start;flex-direction:column;gap:3px}.process-journey-summary{justify-content:space-between}.process-journey-summary small{display:block}.process-journey-track{grid-template-columns:repeat(8,112px)}}
@media(max-width:620px){.property-process-center{padding:12px}.process-center-main{padding:13px}.rental-current-task{grid-template-columns:1fr}.rental-current-task>button{justify-self:start;margin-top:8px}}
/* The overview is a compact status navigator, not a second copy of the stage list. */
.process-journey-map{gap:10px;padding:11px 14px}
.process-journey-head{align-items:center}
.process-journey-title{display:flex!important;align-items:baseline!important;gap:10px!important}
.process-journey-title strong{color:#173f5c;font-size:13px}
.process-journey-title small{color:#718595;font-size:10px}
.process-journey-summary{display:flex!important;align-items:center;gap:7px!important}
.process-journey-summary>span,.process-journey-summary>strong{padding:4px 8px;border-radius:999px;font-size:10px;line-height:1.2;white-space:nowrap}
.process-journey-summary>span{background:#e9f7f7;color:#08717a;font-weight:800}
.process-journey-summary>strong{background:#fff1c9;color:#9a6800}
.process-journey-summary>strong.is-complete{background:#e7f7ed;color:#168047}
.process-journey-track{display:grid;grid-template-columns:repeat(8,minmax(112px,1fr));gap:6px;overflow-x:auto;padding:0 0 2px}
.process-journey-track article{display:flex;min-width:0;align-items:center;gap:7px;border:1px solid #e0e9ed;border-radius:8px;background:#f8fbfc;padding:7px 8px}
.process-journey-track article:not(:last-child)::after{display:none}
.process-journey-track article>span{display:grid;place-items:center;flex:0 0 23px;width:23px;height:23px;border-radius:50%;background:#e6eef1;color:#718595;font-size:9px;font-weight:800}
.process-journey-track article>strong{overflow:hidden;color:#547083;font-size:10px;text-overflow:ellipsis;white-space:nowrap}
.process-journey-track article.is-completed{border-color:#cce5e6;background:#f1fafa}
.process-journey-track article.is-completed>span{background:#0b8f96;color:#fff}
.process-journey-track article.is-completed>strong{color:#176f78}
.process-journey-track article.is-in_progress{border-color:#e7c966;background:#fffaf0;box-shadow:inset 0 -2px #efb500}
.process-journey-track article.is-in_progress>span{background:#efb500;color:#fff}
.process-journey-track article.is-in_progress>strong{color:#8e6200}
@media(max-width:1100px){.process-journey-head{align-items:center}.process-journey-title small{display:none}}
@media(max-width:700px){.process-journey-head{align-items:stretch}.process-journey-title{align-items:flex-start!important;flex-direction:column;gap:2px!important}.process-journey-title small{display:block}.process-journey-summary{justify-content:flex-start}.process-journey-track{grid-template-columns:repeat(8,112px)}}
.process-journey-track button{display:flex;min-width:0;align-items:center;gap:7px;border:1px solid #e0e9ed;border-radius:8px;background:#f8fbfc;padding:7px 8px;color:inherit;font:inherit;text-align:left;cursor:pointer;transition:border-color .15s,box-shadow .15s,transform .15s}
.process-journey-track button:hover{border-color:#91cfd2;transform:translateY(-1px)}
.process-journey-track button.active{border-color:#0b8f96;box-shadow:0 0 0 2px rgba(11,143,150,.13)}
.process-journey-track button>span{display:grid;place-items:center;flex:0 0 23px;width:23px;height:23px;border-radius:50%;background:#e6eef1;color:#718595;font-size:9px;font-weight:800}
.process-journey-track button>strong{overflow:hidden;color:#547083;font-size:10px;text-overflow:ellipsis;white-space:nowrap}
.process-journey-track button.is-completed{border-color:#cce5e6;background:#f1fafa}
.process-journey-track button.is-completed>span{background:#0b8f96;color:#fff}
.process-journey-track button.is-completed>strong{color:#176f78}
.process-journey-track button.is-in_progress{border-color:#e7c966;background:#fffaf0;box-shadow:inset 0 -2px #efb500}
.process-journey-track button.is-in_progress.active{box-shadow:inset 0 -2px #efb500,0 0 0 2px rgba(239,181,0,.17)}
.process-journey-track button.is-in_progress>span{background:#efb500;color:#fff}
.process-journey-track button.is-in_progress>strong{color:#8e6200}
.process-step-page{display:grid;gap:16px;margin-top:14px;padding:17px 18px;border:1px solid #d9e7ea;border-radius:11px;background:linear-gradient(135deg,#fff,#f9fcfd)}
.process-step-page-head{display:flex;align-items:center;justify-content:space-between;gap:18px;padding-bottom:14px;border-bottom:1px solid #e7eef1}
.process-step-heading{display:flex;align-items:center;gap:12px;min-width:0}
.process-step-number{display:grid;place-items:center;flex:0 0 38px;width:38px;height:38px;border-radius:11px;background:#e9f7f7;color:#08717a;font-size:15px;font-weight:800}
.process-step-heading>div{display:grid;gap:3px;min-width:0}
.process-step-heading h4{margin:0;color:#173f5c;font-size:17px}
.process-step-heading p{margin:0;color:#718595;font-size:11px}
.process-step-actions{display:flex;align-items:center;gap:8px}
.process-step-actions>span{padding:5px 9px;border-radius:999px;background:#eef3f5;color:#718595;font-size:10px;font-weight:700;white-space:nowrap}
.process-step-actions>span.is-completed{background:#e7f7ed;color:#168047}
.process-step-actions>span.is-in_progress{background:#fff1c9;color:#9a6800}
.process-step-actions>span.is-blocked{background:#fde7e1;color:#a13f2d}
.process-step-actions button{height:34px;border:1px solid #0b8f96;border-radius:7px;background:#0b8f96;padding:0 13px;color:#fff;font-size:11px;white-space:nowrap}
.process-step-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.process-step-facts article{display:grid;gap:5px;min-width:0;padding:13px 14px;border:1px solid #e3ebee;border-radius:8px;background:#fff}
.process-step-facts article.is-wide{grid-column:span 2}
.process-step-facts span{color:#80929e;font-size:10px}
.process-step-facts strong{overflow:hidden;color:#31556b;font-size:12px;text-overflow:ellipsis;white-space:nowrap}
.process-step-message{margin:0;padding:9px 11px;border-radius:7px;background:#f4f8f9;color:#547083;font-size:11px}
.process-step-message.is-blocked{background:#fff3ef;color:#a13f2d}
.process-step-operations{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px;border:1px solid #cce5e6;border-radius:9px;background:#f1fafa}
@media(max-width:700px){.process-step-page-head,.process-step-operations{align-items:flex-start;flex-direction:column}.process-step-actions{width:100%;justify-content:space-between}.process-step-facts{grid-template-columns:1fr}.process-step-facts article.is-wide{grid-column:auto}.process-step-operations .rental-operations-open-button{width:100%}}
.process-center-layout{display:block;height:auto;min-height:0}
.process-center-main{width:100%}
.process-property-toolbar{display:flex;align-items:center;justify-content:flex-end;gap:10px}
.process-property-toolbar>label{display:flex;align-items:center;gap:7px;color:#718595;font-size:10px}
.process-property-toolbar select{height:34px;min-width:210px;border:1px solid #c9dce2;border-radius:7px;background:#fff;padding:0 28px 0 9px;color:#31556b;font:inherit;font-size:11px}
@media(max-width:620px){.process-property-toolbar{align-items:flex-start;flex-direction:column}.process-property-toolbar>label{align-items:flex-start;flex-direction:column;width:100%}.process-property-toolbar select{width:100%}}
.property-process-center{display:block;padding:12px 18px 24px}
.process-shell{display:grid;grid-template-columns:250px minmax(0,1fr);gap:12px;align-items:start}
.process-context-rail{position:sticky;top:12px;display:grid;align-content:start;gap:16px;min-height:calc(100vh - 104px);box-sizing:border-box;padding:16px;border:1px solid #d9e7ea;border-radius:12px;background:#fff}
.process-context-rail .process-center-header{display:block;padding:0}
.process-context-rail .process-center-header h2{font-size:21px}
.process-context-rail .process-center-header p{font-size:11px;line-height:1.6}
.process-rail-start{width:100%;height:40px}
.process-context-rail .process-property-picker{position:static;display:grid;gap:10px;border:0;border-top:1px solid #e7eef1;border-radius:0;background:transparent;padding:14px 0 0}
.process-context-rail .process-picker-head{margin:0}
.process-context-rail .process-property-picker>input{width:100%;margin:0}
.process-context-rail .process-property-list{width:100%;max-height:calc(100vh - 330px);margin:0;padding:0}
.process-context-rail .process-property-option{padding:9px}
.process-workspace{display:grid;gap:12px;min-width:0}
.process-workspace .process-center-layout{display:block}
@media(max-width:1000px){.process-shell{grid-template-columns:220px minmax(0,1fr)}.process-context-rail{padding:13px}}
@media(max-width:850px){.process-shell{grid-template-columns:1fr}.process-context-rail{position:static;min-height:0}.process-context-rail .process-property-list{max-height:220px}}
.process-journey-track{grid-template-columns:repeat(8,minmax(112px,1fr))}
@media(max-width:700px){.process-journey-track{grid-template-columns:repeat(8,112px)}}
/* Keep the process overview readable on desktop without changing the page density. */
.process-context-rail .process-center-kicker{font-size:12px;line-height:1.4}
.process-context-rail .process-center-header h2{font-size:24px;line-height:1.35}
.process-context-rail .process-center-header p{font-size:13px;line-height:1.65}
.process-journey-map{gap:12px;padding:14px 16px}
.process-journey-title strong{font-size:16px;line-height:1.35}
.process-journey-title small{font-size:12px;line-height:1.4}
.process-journey-summary>span,.process-journey-summary>strong{padding:5px 9px;font-size:12px}
.process-journey-track{gap:8px}
.process-journey-track button{min-height:44px;gap:8px;padding:8px 10px}
.process-journey-track button>span{flex-basis:28px;width:28px;height:28px;font-size:11px}
